#include <iostream>
struct B1 {
    B1() { std::cout << "B1 default constructor" << std::endl; }
    B1(int x) { std::cout << "B1 parameterized constructor: " << x << std::endl; }
};
struct B2 {
    B2() { std::cout << "B2 default constructor" << std::endl; }
    B2(int y) { std::cout << "B2 parameterized constructor: " << y << std::endl; }
};
struct D2 : B1, B2 {
    using B1::B1;
    using B2::B2;
    D2(int val) { std::cout << "D2 constructor with value: " << val << std::endl; }
};
int main() {
    D2 obj1; // Calls B1() and B2() implicitly
    D2 obj2(42); // Calls D2(int), B1(int), B2(int)
    return 0;
}
